func TestNewRetry(t *testing.T) {
	t.Run("produces positive backoff for early attempts", func(t *testing.T) {
		h, err := libp2p.New(libp2p.ListenAddrStrings("/ip4/127.0.0.1/tcp/0"))
		require.NoError(t, err)
		defer h.Close()

		s := newRetry(h)
		require.NotNil(t, s)

		for attempt := int64(0); attempt < 5; attempt++ {
			require.Positive(t, s.Backoff(attempt))
		}
	})

	t.Run("respects the maximum bound for large attempts", func(t *testing.T) {
		h, err := libp2p.New(libp2p.ListenAddrStrings("/ip4/127.0.0.1/tcp/0"))
		require.NoError(t, err)
		defer h.Close()

		s := newRetry(h)

		for attempt := int64(10); attempt < 20; attempt++ {
			d := s.Backoff(attempt)
			require.LessOrEqual(t, d, time.Minute+reserveJitterWindow)
		}
	})

	t.Run("exponential growth is bounded by base plus jitter", func(t *testing.T) {
		h, err := libp2p.New(libp2p.ListenAddrStrings("/ip4/127.0.0.1/tcp/0"))
		require.NoError(t, err)
		defer h.Close()

		s := newRetry(h)

		for attempt := int64(0); attempt < 6; attempt++ {
			d := s.Backoff(attempt)
			base := time.Second * time.Duration(1<<attempt)
			require.GreaterOrEqual(t, d, base)
			require.LessOrEqual(t, d, base+reserveJitterWindow)
		}
	})

	t.Run("different hosts produce different jitter values", func(t *testing.T) {
		h1, err := libp2p.New(libp2p.ListenAddrStrings("/ip4/127.0.0.1/tcp/0"))
		require.NoError(t, err)
		defer h1.Close()

		h2, err := libp2p.New(libp2p.ListenAddrStrings("/ip4/127.0.0.1/tcp/0"))
		require.NoError(t, err)
		defer h2.Close()

		s1 := newRetry(h1)
		s2 := newRetry(h2)

		values1 := make([]time.Duration, 10)
		values2 := make([]time.Duration, 10)
		for i := range values1 {
			values1[i] = s1.Backoff(int64(i))
			values2[i] = s2.Backoff(int64(i))
		}

		differ := false
		for i := range values1 {
			if values1[i] != values2[i] {
				differ = true
				break
			}
		}
		require.True(t, differ)
	})
}
